class Solution:
    def maximumSwap(self, num: int) -> int:
        digits = list(str(num))
        best = num
        for i in range(len(digits)):
            for j in range(i, len(digits)):
                arr = digits[:]
                arr[i], arr[j] = arr[j], arr[i]
                best = max(best, int(''.join(arr)))
        return best

