class Solution:
    def maximumSwap(self, num):
        digits = list(str(num))
        n = len(digits)
        best_idx = [0] * n
        best_idx[-1] = n - 1
        for i in range(n - 2, -1, -1):
            if digits[i] > digits[best_idx[i + 1]]:
                best_idx[i] = i
            else:
                best_idx[i] = best_idx[i + 1]
        for i in range(n):
            j = best_idx[i]
            if digits[j] > digits[i]:
                digits[i], digits[j] = digits[j], digits[i]
                break
        return int(''.join(digits))

